import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 7
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    prefix = []
    for record in reader:
        if len(record) == expected_width and any(cell.strip() for cell in record):
            columns = record
            rows = list(reader)
            break
        prefix.append(record)
    else:
        for index, record in enumerate(prefix):
            if any(cell.strip() for cell in record):
                columns = record
                rows = prefix[index + 1:]
                break
        else:
            return {"columns": [], "rows": []}

    width = max(expected_width, len(columns))
    for row in rows:
        width = max(width, len(row))

    used_names = set(columns)
    for index in range(len(columns), width):
        name = f"extra_{index + 1}"
        while name in used_names:
            name += "_"
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
